    INSERT INTO questions (chapitre_id, enonce, choix, bonne_reponse, explication, niveau_complexite) VALUES
    (chap_id, 'Qu''est-ce que la "mondialisation" en géographie ?', '["La colonisation progressive des pays pauvres par les pays riches", "Le processus d''intensification des échanges économiques, culturels, politiques et humains à l''échelle planétaire", "L''uniformisation complète des cultures mondiales", "La domination militaire des États-Unis sur le monde"]'::jsonb, 'Le processus d''intensification des échanges économiques, culturels, politiques et humains à l''échelle planétaire', 'La mondialisation désigne l''intensification des flux (marchandises, capitaux, personnes, informations, cultures) à l''échelle planétaire. Elle s''est accélérée depuis les années 1980 grâce aux progrès technologiques (transport, télécommunications), à la libéralisation des échanges et à l''essor du capitalisme financier.', 'Facile'),
    (chap_id, 'Qu''est-ce que la "géopolitique" en tant que discipline ?', '["L''étude des ressources naturelles mondiales", "L''étude des relations entre les États, les territoires et le pouvoir, incluant les conflits, les alliances et les influences géographiques sur la politique", "L''étude de la distribution géographique des populations", "La gestion des frontières internationales par des organismes internationaux"]'::jsonb, 'L''étude des relations entre les États, les territoires et le pouvoir, incluant les conflits, les alliances et les influences géographiques sur la politique', 'La géopolitique analyse les relations de pouvoir entre les acteurs (États, organisations, multinationales) dans leur dimension spatiale et territoriale. Elle étudie comment la géographie (ressources, frontières, positions stratégiques) influence les décisions politiques et les conflits.', 'Facile'),
    (chap_id, 'Qu''est-ce qu''un "État pivot" ou "heartland" dans la théorie géopolitique de Mackinder ?', '["Un pays côtier dominant le commerce maritime", "Le cœur continental eurasien dont le contrôle, selon Mackinder, donnerait la domination mondiale", "Un petit pays situé entre deux grandes puissances", "Une zone géographique riche en ressources pétrolières"]'::jsonb, 'Le cœur continental eurasien dont le contrôle, selon Mackinder, donnerait la domination mondiale', 'Halford Mackinder (1904) théorisa que le contrôle du "Heartland" (cœur continental de l''Eurasie, grossièrement la Russie et l''Asie centrale) donnerait la domination mondiale. Sa formule : "Qui gouverne le Heartland commande l''Ile du Monde ; qui gouverne l''Ile du Monde commande le Monde."', 'Difficile'),
    (chap_id, 'Quels sont les principaux acteurs de la mondialisation économique au-delà des États ?', '["Seulement les organisations régionales comme l''UE et la CARICOM", "Les firmes multinationales (FMN), les organisations internationales (OMC, FMI, BM) et les marchés financiers", "Seulement les banques centrales nationales", "Les partis politiques internationaux"]'::jsonb, 'Les firmes multinationales (FMN), les organisations internationales (OMC, FMI, BM) et les marchés financiers', 'Outre les États, les principaux acteurs de la mondialisation sont les firmes multinationales (FMN) qui organisent la production à l''échelle mondiale, les organisations internationales (OMC pour le commerce, FMI et Banque Mondiale pour les finances), et les marchés financiers qui constituent un espace transnational de plus en plus autonome.', 'Moyen'),
    (chap_id, 'Qu''est-ce qu''un "BRICS" en géopolitique mondiale ?', '["Un bloc militaire occidental regroupant le Brésil, la Russie, l''Inde, la Chine et l''Afrique du Sud", "Un groupe informel de grandes économies émergentes (Brésil, Russie, Inde, Chine, Afrique du Sud) qui cherchent à peser dans les affaires mondiales", "Une organisation économique rivale de l''OCDE réservée aux pays pauvres", "Un traité de libre-échange entre les pays du Sud"]'::jsonb, 'Un groupe informel de grandes économies émergentes (Brésil, Russie, Inde, Chine, Afrique du Sud) qui cherchent à peser dans les affaires mondiales', 'Les BRICS (Brésil, Russie, Inde, Chine, Afrique du Sud) sont des économies émergentes qui revendiquent un rôle accru dans la gouvernance mondiale. Depuis 2024, le groupe a été élargi à plusieurs nouveaux membres (Éthiopie, Iran, Arabie Saoudite, EAU, Égypte, Argentine). Ils contestent l''ordre mondial dominé par les pays occidentaux.', 'Moyen'),
    (chap_id, 'Qu''est-ce que les "Nord-Sud" et les "inégalités mondiales de développement" désignent en géographie ?', '["La différence climatique entre l''hémisphère nord et l''hémisphère sud", "L''écart de développement économique et humain entre les pays riches (Nord) et les pays pauvres (Sud), bien que cette division soit de moins en moins pertinente", "Un conflit politique entre les pays européens et africains", "La distribution des ressources naturelles entre les deux hémisphères"]'::jsonb, 'L''écart de développement économique et humain entre les pays riches (Nord) et les pays pauvres (Sud), bien que cette division soit de moins en moins pertinente', 'La fracture Nord-Sud désignait traditionnellement l''écart de développement entre les pays riches (Europe, Amérique du Nord, Japon) et les pays pauvres (Afrique, Asie du Sud, Amérique latine). Cette vision binaire est désormais nuancée par l''émergence des BRICS et les inégalités croissantes au sein des pays "riches".', 'Moyen'),
    (chap_id, 'Qu''est-ce que le "Consensus de Washington" et comment a-t-il influencé les pays en développement comme Haïti ?', '["Un accord de paix entre les États-Unis et l''Amérique latine", "Un ensemble de prescriptions économiques libérales (privatisation, déréglementation, austérité) imposées par le FMI et la Banque Mondiale aux pays en développement", "Un traité d''intégration économique des Amériques", "Une déclaration sur les droits de l''homme signée à Washington"]'::jsonb, 'Un ensemble de prescriptions économiques libérales (privatisation, déréglementation, austérité) imposées par le FMI et la Banque Mondiale aux pays en développement', 'Le Consensus de Washington (années 1980-2000) désigne les prescriptions économiques néolibérales (privatisation des entreprises publiques, libéralisation du commerce, réduction des dépenses publiques, rigueur monétaire) que le FMI et la Banque Mondiale ont conditionnées à leur aide. Appliquées en Haïti, ces mesures ont eu des effets controversés sur l''agriculture et l''industrie locales.', 'Difficile'),
    (chap_id, 'Quel est l''enjeu géopolitique des détroits maritimes comme le Détroit d''Ormuz ou le Canal de Suez ?', '["Ils servent uniquement à la pêche industrielle", "Ce sont des points de passage obligés du commerce maritime mondial dont le contrôle confère un pouvoir géopolitique considérable", "Ils sont des frontières naturelles entre des États en guerre", "Leur importance est purement touristique"]'::jsonb, 'Ce sont des points de passage obligés du commerce maritime mondial dont le contrôle confère un pouvoir géopolitique considérable', 'Les détroits et canaux stratégiques (Ormuz pour le pétrole du Golfe, Suez pour le commerce Europe-Asie, Panama pour l''Atlantique-Pacifique, Malacca pour l''Asie du Sud-Est) sont des "choke points" : leur contrôle ou leur blocage peut paralyser des pans entiers du commerce mondial, conférant un pouvoir géopolitique immense à qui les contrôle.', 'Difficile'),
    (chap_id, 'Qu''est-ce que la "fracture numérique" dans le contexte de la mondialisation ?', '["La distinction entre l''internet fixe et l''internet mobile", "L''inégalité d''accès aux technologies de l''information entre les pays développés et en développement, et au sein même des sociétés", "La différence de vitesse internet entre les pays du Nord et du Sud", "La domination des entreprises américaines dans le domaine du numérique"]'::jsonb, 'L''inégalité d''accès aux technologies de l''information entre les pays développés et en développement, et au sein même des sociétés', 'La fracture numérique désigne les inégalités d''accès aux TIC (internet, ordinateurs, smartphones) entre pays riches et pauvres, mais aussi au sein de chaque société (entre générations, niveaux d''éducation, zones urbaines/rurales). Haïti illustre cette fracture : accès internet limité, coûts élevés, infrastructure défaillante.', 'Moyen'),
    (chap_id, 'Qu''est-ce que l''"hégémonie américaine" dans le contexte de l''ordre mondial post-1945 ?', '["La domination militaire des États-Unis sur l''Europe uniquement", "La prédominance des États-Unis dans les domaines militaire, économique, diplomatique et culturel, définissant les règles de l''ordre mondial contemporain", "Le contrôle américain de toutes les organisations internationales", "La supériorité technologique américaine dans le domaine spatial"]'::jsonb, 'La prédominance des États-Unis dans les domaines militaire, économique, diplomatique et culturel, définissant les règles de l''ordre mondial contemporain', 'L''hégémonie américaine désigne la prépondérance des États-Unis dans les affaires mondiales depuis 1945, renforcée après 1991. Elle s''exprime par la puissance militaire (OTAN), la suprématie économique (dollar, FMI, Banque Mondiale), la soft power culturel (Hollywood, Silicon Valley) et le cadre diplomatique (ONU basée à New York).', 'Difficile'),
    (chap_id, 'Quel rôle jouent les "zones économiques exclusives" (ZEE) dans les rivalités géopolitiques marines ?', '["Elles servent uniquement à protéger les espèces marines en voie d''extinction", "Elles accordent à un État des droits exclusifs sur les ressources (pêche, hydrocarbures) de 200 milles nautiques depuis ses côtes, source de nombreux conflits", "Elles définissent les eaux où la navigation de plaisance est interdite", "Elles sont des zones de libre-échange maritime"]'::jsonb, 'Elles accordent à un État des droits exclusifs sur les ressources (pêche, hydrocarbures) de 200 milles nautiques depuis ses côtes, source de nombreux conflits', 'La ZEE (issue de la Convention de Montego Bay, 1982) accorde aux États des droits économiques exclusifs sur 200 milles nautiques depuis leurs côtes. Elle est source de nombreux conflits (mer de Chine méridionale, Arctique) car elle délimite l''accès aux ressources halieutiques et pétrolières sous-marines.', 'Difficile'),
    (chap_id, 'Qu''est-ce que la "géographie des inégalités" mesure à l''échelle mondiale ?', '["La distribution des richesses naturelles entre les continents", "Les disparités spatiales de développement humain, économique et social entre les pays et au sein des pays, cartographiées pour visualiser les inégalités territoriales", "La différence de superficie entre les grands et les petits États", "La localisation des conflits armés dans le monde"]'::jsonb, 'Les disparités spatiales de développement humain, économique et social entre les pays et au sein des pays, cartographiées pour visualiser les inégalités territoriales', 'La géographie des inégalités cartographie et analyse les disparités spatiales de PIB, d''IDH, d''accès aux services de base, d''espérance de vie, etc. à différentes échelles. Ces cartes révèlent des fractures persistantes (Afrique sub-saharienne, zones rurales, périphéries urbaines) et des dynamiques nouvelles (émergence asiatique).', 'Moyen'),
    (chap_id, 'Comment le changement climatique remodèle-t-il la géopolitique mondiale au XXIe siècle ?', '["Il n''a pas d''impact sur les relations entre États", "Il crée de nouvelles tensions sur les ressources en eau, déplace des populations, ouvre de nouvelles routes arctiques et amplifie les vulnérabilités des États fragiles", "Il conduit à une coopération internationale harmonieuse", "Il avantage uniquement les pays du nord en leur donnant de nouvelles terres agricoles"]'::jsonb, 'Il crée de nouvelles tensions sur les ressources en eau, déplace des populations, ouvre de nouvelles routes arctiques et amplifie les vulnérabilités des États fragiles', 'Le changement climatique est devenu un enjeu géopolitique majeur : il intensifie les compétitions pour les ressources en eau (stress hydrique), génère des migrations climatiques, ouvre la course à l''Arctique (nouvelles routes maritimes, ressources pétrolières), et aggrave l''instabilité des États fragiles comme Haïti, exposés aux catastrophes naturelles amplifiées.', 'Difficile'),
    (chap_id, 'Qu''est-ce que le "soft power" dans la géopolitique contemporaine ?', '["La puissance militaire non-nucléaire d''un État", "La capacité d''un acteur à influencer le comportement des autres par l''attraction culturelle, les valeurs et la diplomatie plutôt que par la coercition", "La force économique d''un pays mesurée par son PIB", "La diplomatie secrète menée hors des canaux officiels"]'::jsonb, 'La capacité d''un acteur à influencer le comportement des autres par l''attraction culturelle, les valeurs et la diplomatie plutôt que par la coercition', 'Le "soft power" (concept de Joseph Nye) désigne la capacité d''influencer sans contrainte : culture populaire, langue, universités, aide au développement, diplomatie. Les États-Unis exercent un soft power mondial (Hollywood, Silicon Valley, universités), tout comme la France (francophonie, gastronomie) ou la Chine (Instituts Confucius, nouvelles routes de la soie).', 'Difficile'),
    (chap_id, 'Quel continent est le plus concerné par la problématique du développement et de la pauvreté dans la géopolitique mondiale contemporaine ?', '["L''Amérique latine", "L''Asie du Sud-Est", "L''Afrique sub-saharienne", "L''Europe de l''Est"]'::jsonb, 'L''Afrique sub-saharienne', 'L''Afrique sub-saharienne concentre la majorité des pays les moins avancés (PMA), des situations de pauvreté extrême et d''insécurité alimentaire. Cependant, certains pays (Éthiopie, Côte d''Ivoire, Rwanda, Kenya) connaissent des dynamiques de développement significatives. L''Afrique sub-saharienne est aussi le continent avec la plus forte croissance démographique.', 'Moyen'),
    (chap_id, 'Qu''est-ce que les "nouvelles routes de la soie" (Belt and Road Initiative) de la Chine ?', '["Une politique de préservation des routes commerciales médiévales", "Un vaste projet d''infrastructure (routes, ports, chemins de fer, pipelines) financé par la Chine pour renforcer son influence économique et géopolitique mondiale", "Un accord de libre-échange entre la Chine et l''Asie centrale", "Un projet culturel de promotion de la civilisation chinoise"]'::jsonb, 'Un vaste projet d''infrastructure (routes, ports, chemins de fer, pipelines) financé par la Chine pour renforcer son influence économique et géopolitique mondiale', 'Lancée en 2013 par Xi Jinping, la BRI (Belt and Road Initiative) est un projet d''infrastructures gigantesque (>100 pays, >$1000 milliards). Elle vise à connecter la Chine à l''Asie, l''Afrique, l''Europe et l''Amérique latine par des routes, ports et chemins de fer financés par des prêts chinois, renforçant l''influence géopolitique de Pékin.', 'Difficile'),
    (chap_id, 'Quel est le rôle de l''Organisation des Nations Unies (ONU) dans l''ordre géopolitique mondial ?', '["Un gouvernement mondial supranational qui impose ses décisions aux États", "Un forum de coopération internationale et de médiation des conflits dont les résolutions sont politiquement mais pas toujours légalement contraignantes", "Une organisation militaire comme l''OTAN", "Une banque de développement pour les pays pauvres"]'::jsonb, 'Un forum de coopération internationale et de médiation des conflits dont les résolutions sont politiquement mais pas toujours légalement contraignantes', 'L''ONU (fondée en 1945, 193 membres) est la principale organisation de coopération internationale. Le Conseil de Sécurité (5 membres permanents avec droit de veto : USA, Russie, Chine, France, Royaume-Uni) peut voter des résolutions contraignantes, mais son efficacité est limitée par le jeu des vetos et la souveraineté des États.', 'Moyen'),
    (chap_id, 'Comment les flux migratoires mondiaux illustrent-ils les inégalités géographiques mondiales ?', '["Les migrations sont aléatoires et ne suivent aucune logique géographique", "Les migrations suivent principalement un axe Sud-Nord ou des zones de conflits vers des zones stables, reflétant les inégalités de développement et de sécurité", "Les migrations mondiales se font principalement entre pays du même niveau de développement", "Les migrations sont surtout motivées par des facteurs culturels et religieux, non économiques"]'::jsonb, 'Les migrations suivent principalement un axe Sud-Nord ou des zones de conflits vers des zones stables, reflétant les inégalités de développement et de sécurité', 'Les flux migratoires mondiaux reflètent les inégalités géopolitiques : ils suivent un axe Sud-Nord (Afrique-Europe, Amérique latine-Amérique du Nord) et des zones de conflits vers des zones stables (Syrie, Myanmar, Afghanistan). Haïti est un émetteur majeur de migrants vers les États-Unis, le Canada et la République Dominicaine, en raison des crises politiques et économiques.', 'Moyen');
    INSERT INTO questions (chapitre_id, enonce, choix, bonne_reponse, explication, niveau_complexite) VALUES
    (chap_id, 'Quel événement géopolitique majeur d''Haïti a marqué son isolement international au XIXe siècle ?', '["La signature du Traité de Ryswick", "Le paiement de l''indemnité de 150 millions de francs-or à la France pour la reconnaissance de son indépendance (1825)", "La création de la première constitution haïtienne", "L''intégration d''Haïti dans l''Organisation des États Américains"]'::jsonb, 'Le paiement de l''indemnité de 150 millions de francs-or à la France pour la reconnaissance de son indépendance (1825)', 'En 1825, Haïti accepta de payer 150 millions de francs-or (réduit à 90 millions en 1838) à la France pour être reconnue internationalement. Cette dette colossale, remboursée jusqu''en 1947, a lourdement hypothéqué le développement haïtien et symbolise l''extorsion coloniale post-indépendance.', 'Moyen'),
    (chap_id, 'Pourquoi l''Occupation américaine d''Haïti (1915-1934) reste-t-elle un enjeu géopolitique sensible dans les relations haïtiano-américaines ?', '["Parce qu''elle a apporté la démocratie à Haïti", "Parce qu''elle a violé la souveraineté haïtienne, refait la constitution pour favoriser les intérêts américains, et laissé des traces traumatiques dans la mémoire collective haïtienne", "Parce qu''elle a créé l''armée haïtienne", "Parce qu''elle a résolu tous les problèmes économiques d''Haïti"]'::jsonb, 'Parce qu''elle a violé la souveraineté haïtienne, refait la constitution pour favoriser les intérêts américains, et laissé des traces traumatiques dans la mémoire collective haïtienne', 'L''Occupation américaine (1915-1934) est perçue comme une humiliation nationale : elle a violé la souveraineté d''Haïti, imposé une nouvelle constitution permettant la propriété foncière aux étrangers, confisqué les douanes haïtiennes, et provoqué des résistances (notamment la révolte Cacos). Elle a laissé une méfiance durable envers l''ingérence américaine.', 'Moyen'),
    (chap_id, 'Quel est le principal enjeu géopolitique des relations entre Haïti et la République Dominicaine ?', '["La rivalité pour le contrôle de la mer des Caraïbes", "La question des migrations haïtiennes en RD, les travailleurs haïtiens en situation précaire, et les tensions historiques liées aux massacres de 1937", "Le contrôle des ressources minières de l''île d''Hispaniola", "Les différends sur la frontière maritime"]'::jsonb, 'La question des migrations haïtiennes en RD, les travailleurs haïtiens en situation précaire, et les tensions historiques liées aux massacres de 1937', 'Les relations Haïti-RD sont complexes : des centaines de milliers d''Haïtiens travaillent en RD dans des conditions souvent précaires (agriculture, construction). Les tensions sont alimentées par le souvenir du massacre de 1937 (Parsley Massacre sous Trujillo), les politiques dominicaines sur la nationalité, et les tensions migratoires récurrentes.', 'Difficile'),
    (chap_id, 'Qu''est-ce que le MINUSTAH et quel rôle a-t-il joué en Haïti ?', '["Une organisation économique régionale fondée en 2004 par Haïti", "La Mission des Nations Unies pour la Stabilisation en Haïti (2004-2017), force de maintien de la paix déployée après la chute d''Aristide", "Un programme d''aide humanitaire américain", "Une alliance militaire haïtiano-caribéenne"]'::jsonb, 'La Mission des Nations Unies pour la Stabilisation en Haïti (2004-2017), force de maintien de la paix déployée après la chute d''Aristide', 'La MINUSTAH (2004-2017) était une force multinationale de l''ONU déployée en Haïti après la destitution du président Aristide. Composée principalement de soldats latino-américains (Brésil en tête), elle a été controversée en raison de l''introduction du choléra (2010) et de scandales d''abus sexuels. Elle a été remplacée par la MINUJUSTH puis d''autres mécanismes.', 'Moyen'),
    (chap_id, 'Comment la position géographique d''Haïti dans les Caraïbes influence-t-elle ses relations avec les États-Unis ?', '["Haïti est trop éloignée pour intéresser les États-Unis géopolitiquement", "La proximité géographique (à 800 km de la Floride) fait d''Haïti une préoccupation géopolitique américaine : migrations, narco-trafic, instabilité politique", "Les États-Unis considèrent Haïti comme un allié stratégique militaire majeur", "La position d''Haïti n''a aucune pertinence pour la politique américaine dans la région"]'::jsonb, 'La proximité géographique (à 800 km de la Floride) fait d''Haïti une préoccupation géopolitique américaine : migrations, narco-trafic, instabilité politique', 'Haïti est à environ 800 km de la Floride. Cette proximité fait d''Haïti une préoccupation géopolitique permanente pour Washington : les vagues migratoires haïtiennes (boat people, exils politiques), le passage de la drogue via Haïti vers les États-Unis, et la crainte d''une instabilité régionale expliquent les nombreuses interventions américaines.', 'Moyen'),
    (chap_id, 'Quel est l''impact géopolitique de la crise des gangs en Haïti sur les relations internationales depuis 2021 ?', '["Les gangs ont favorisé la stabilisation d''Haïti", "La montée en puissance des gangs armés a paralysé l''État haïtien, provoqué une crise humanitaire et des migrations massives, attirant des interventions étrangères controversées", "La crise des gangs est purement interne et sans impact international", "Les gangs ont facilité le dialogue politique entre les factions haïtiennes"]'::jsonb, 'La montée en puissance des gangs armés a paralysé l''État haïtien, provoqué une crise humanitaire et des migrations massives, attirant des interventions étrangères controversées', 'Depuis 2021 (assassinat du président Moïse), la montée des gangs armés à Port-au-Prince a paralysé l''État et créé une crise humanitaire grave (déplacements internes, famine, violences). Elle a généré des flux migratoires vers les États-Unis et la RD, et conduit au déploiement d''une mission multinationale kényane en 2024 sous mandat de l''ONU.', 'Difficile'),
    (chap_id, 'Quel est le rôle de l''aide internationale dans la géopolitique haïtienne ?', '["L''aide internationale est mineure et sans impact sur la politique haïtienne", "L''aide internationale (ONG, bailleurs de fonds) représente une fraction importante du budget haïtien et crée une relation de dépendance qui influence la souveraineté de l''État haïtien", "L''aide internationale est uniquement militaire", "L''aide internationale a résolu définitivement les problèmes d''Haïti"]'::jsonb, 'L''aide internationale (ONG, bailleurs de fonds) représente une fraction importante du budget haïtien et crée une relation de dépendance qui influence la souveraineté de l''État haïtien', 'L''aide internationale représente une part significative des ressources haïtiennes (aide bilatérale des États-Unis, Canada, UE, et multilatérale de l''ONU, BM, FMI). Cette dépendance crée une relation complexe où les bailleurs exercent une influence sur les politiques haïtiennes, soulevant des questions sur la souveraineté nationale et l''efficacité de l''aide.', 'Difficile'),
    (chap_id, 'Quel défi environnemental menace la géopolitique interne d''Haïti en accentuant les inégalités et les migrations internes ?', '["La montée des eaux dans les zones côtières uniquement", "La déforestation massive (moins de 2 % de couvert forestier), qui provoque érosion, inondations, glissements de terrain et insécurité alimentaire, forçant des déplacements de populations rurales", "La pollution industrielle des villes", "La surpêche dans les eaux territoriales haïtiennes"]'::jsonb, 'La déforestation massive (moins de 2 % de couvert forestier), qui provoque érosion, inondations, glissements de terrain et insécurité alimentaire, forçant des déplacements de populations rurales', 'La déforestation haïtienne (passée de 60 % de couvert forestier au XIXe siècle à moins de 2 % aujourd''hui) est une catastrophe environnementale qui amplifie les catastrophes naturelles (inondations, glissements), détruit les terres agricoles, provoque la migration rurale-urbaine et menace la survie d''innombrables communautés rurales.', 'Moyen'),
    (chap_id, 'Comment l''assassinat du président Jovenel Moïse en juillet 2021 a-t-il reconfiguré la géopolitique haïtienne ?', '["Il a entraîné des élections ordonnées et une transition pacifique", "Il a plongé Haïti dans un vide institutionnel profond, avec une lutte de pouvoir entre factions, aggravant la domination des gangs et l''insécurité", "Il a conduit à une intervention américaine directe", "Il a eu peu d''impact sur la situation politique haïtienne"]'::jsonb, 'Il a plongé Haïti dans un vide institutionnel profond, avec une lutte de pouvoir entre factions, aggravant la domination des gangs et l''insécurité', 'L''assassinat de Jovenel Moïse (7 juillet 2021) a créé un vide constitutionnel : pas de Parlement fonctionnel depuis 2020, pas de Cour Suprême complète, rivalités entre clans politiques. Ce vide a permis aux gangs de contrôler des pans entiers du territoire haïtien, plongeant le pays dans une crise humanitaire sans précédent.', 'Difficile'),
    (chap_id, 'Quel pays d''Afrique a été mandaté par l''ONU pour diriger la Mission Multinationale de Soutien à la Sécurité en Haïti en 2024 ?', '["Le Nigeria", "Le Kenya", "L''Afrique du Sud", "Le Rwanda"]'::jsonb, 'Le Kenya', 'Le Kenya a accepté de diriger la Mission Multinationale de Soutien à la Sécurité (MMSS) en Haïti, autorisée par la résolution 2699 du Conseil de Sécurité de l''ONU (octobre 2023). Les forces kényanes ont commencé à se déployer en Haïti en 2024 pour aider à lutter contre les gangs armés.', 'Difficile'),
    (chap_id, 'Quel est le poids géopolitique de la diaspora haïtienne dans les pays d''accueil ?', '["La diaspora n''a aucune influence politique dans les pays d''accueil", "La diaspora haïtienne aux États-Unis, au Canada et en France exerce une influence politique (vote, lobbying), envoie des remises et maintient des liens avec Haïti", "La diaspora haïtienne est trop petite pour avoir un impact politique", "La diaspora haïtienne est uniquement économique, sans dimension politique"]'::jsonb, 'La diaspora haïtienne aux États-Unis, au Canada et en France exerce une influence politique (vote, lobbying), envoie des remises et maintient des liens avec Haïti', 'La diaspora haïtienne (2-3 millions de personnes dans le monde) a une importance géopolitique croissante : elle influence les politiques d''immigration américaines, canadiennes et françaises, envoie des remises vitales pour l''économie haïtienne, et ses figures (politiciens, intellectuels, artistes) pèsent dans les discussions sur l''avenir d''Haïti.', 'Moyen'),
    (chap_id, 'Pourquoi Haïti est-elle considérée comme un "État fragile" dans la terminologie géopolitique internationale ?', '["Parce qu''elle n''a pas de constitution ni de lois", "Parce que ses institutions étatiques (gouvernement, justice, armée, services publics) sont trop faibles pour assurer leurs fonctions régaliennes sur tout le territoire", "Parce qu''elle est trop petite géographiquement pour être un État viable", "Parce qu''elle manque de ressources naturelles"]'::jsonb, 'Parce que ses institutions étatiques (gouvernement, justice, armée, services publics) sont trop faibles pour assurer leurs fonctions régaliennes sur tout le territoire', 'Un "État fragile" est un État dont les institutions sont trop faibles pour exercer pleinement les fonctions régaliennes (sécurité, justice, services publics, collecte des impôts) sur l''ensemble de son territoire. Haïti correspond à cette définition : gouvernement instable, absence de monopole de la violence, justice défaillante, services publics quasi inexistants.', 'Moyen'),
    (chap_id, 'Quel instrument juridique international régit les relations entre États en matière de commerce et comment affecte-t-il Haïti ?', '["La Convention de Genève sur les droits des réfugiés", "L''Organisation Mondiale du Commerce (OMC) et ses accords de libre-échange qui ont parfois nui à la production locale haïtienne (riz, textiles)", "Le Traité de Rome sur la Cour Pénale Internationale", "La Convention des Nations Unies sur le Droit de la Mer (UNCLOS)"]'::jsonb, 'L''Organisation Mondiale du Commerce (OMC) et ses accords de libre-échange qui ont parfois nui à la production locale haïtienne (riz, textiles)', 'L''OMC régit le commerce international. La libéralisation commerciale imposée à Haïti dans les années 1990-2000 a eu des effets controversés : la baisse des droits de douane sur le riz américain subventionné a détruit une grande partie de la production locale de riz haïtien, aggravant la dépendance alimentaire et la pauvreté rurale.', 'Difficile'),
    (chap_id, 'Comment la question de la reconstruction post-séisme de 2010 illustre les paradoxes de l''aide internationale en Haïti ?', '["La reconstruction s''est faite efficacement grâce à une coordination internationale exemplaire", "Malgré des milliards de dollars promis, la reconstruction a été lente, mal coordonnée, avec des scandales d''ONG, et n''a pas résolu les problèmes structurels d''Haïti", "La reconstruction a été entièrement financée par la diaspora haïtienne", "Le séisme de 2010 n''a pas généré d''aide internationale significative"]'::jsonb, 'Malgré des milliards de dollars promis, la reconstruction a été lente, mal coordonnée, avec des scandales d''ONG, et n''a pas résolu les problèmes structurels d''Haïti', 'Malgré 13 milliards de dollars promis après le séisme de 2010, la reconstruction haïtienne a été emblématique de l''échec de l''aide internationale : prolifération anarchique d''ONG peu coordonnées, scandales d''exploitation sexuelle (Oxfam), détournements, construction de logements inadaptés. Un décennie plus tard, des camps de déplacés subsistaient encore.', 'Difficile'),
    (chap_id, 'Quel est l''impact du trafic de drogues sur la géopolitique d''Haïti ?', '["Haïti n''est pas touchée par le trafic de drogues", "Haïti est utilisée comme point de transit pour la cocaïne sud-américaine vers les États-Unis et l''Europe, ce qui finance les gangs et corrompt les institutions", "Le trafic de drogues est entièrement contrôlé par l''État haïtien", "Haïti est un pays producteur de cocaïne"]'::jsonb, 'Haïti est utilisée comme point de transit pour la cocaïne sud-américaine vers les États-Unis et l''Europe, ce qui finance les gangs et corrompt les institutions', 'La position géographique d''Haïti (entre la Colombie/Venezuela productrices et les États-Unis consommateurs) en fait une plaque tournante du trafic de cocaïne. Ce trafic génère des revenus qui financent les gangs armés, corrompent les institutions (police, douanes, politique) et aggravent l''insécurité, tout en amplifiant les préoccupations géopolitiques américaines.', 'Difficile'),
    (chap_id, 'Quel accord régional donne à Haïti des préférences commerciales pour ses exportations textiles vers les États-Unis ?', '["L''ALENA (NAFTA)", "L''accord HOPE/HELP Act", "Le CAFTA-DR", "Le Caribbean Basin Initiative (CBI) complété par les lois HOPE I (2006) et HOPE II (2008)"]'::jsonb, 'Le Caribbean Basin Initiative (CBI) complété par les lois HOPE I (2006) et HOPE II (2008)', 'Le Caribbean Basin Initiative (CBI) accorde des préférences commerciales aux pays caribéens. Pour Haïti spécifiquement, les lois HOPE I (2006) et HOPE II (2008), promulguées par le Congrès américain, accordent des accès préférentiels aux exportations textiles haïtiennes vers les États-Unis, soutenant l''industrie d''assemblage haïtienne qui emploie des dizaines de milliers de personnes.', 'Difficile'),
    (chap_id, 'Comment la question de la frontière Haïti-République Dominicaine est-elle devenue un enjeu géopolitique majeur depuis 2023 ?', '["La RD a réclamé des territoires haïtiens supplémentaires", "La construction d''un mur frontalier par la RD et les tensions migratoires ont cristallisé les tensions bilatérales et suscité des débats sur les droits des migrants haïtiens", "La frontière a été ouverte totalement entre les deux pays", "La RD et Haïti ont signé un accord de fusion politique"]'::jsonb, 'La construction d''un mur frontalier par la RD et les tensions migratoires ont cristallisé les tensions bilatérales et suscité des débats sur les droits des migrants haïtiens', 'La construction d''un mur à la frontière haïtiano-dominicaine annoncée par le gouvernement Abinader en 2022-2023, les déportations massives d''Haïtiens de RD, et les accusations de violations des droits humains ont exacerbé les tensions bilatérales, révélant la fragilité des relations entre les deux nations partageant l''île d''Hispaniola.', 'Difficile');
